contract InvMutTest {
    C public c;
    constructor(C _c) { c = _c; }

    // Drive the contract: caller attempts to burn and we check who caused totalSupply to drop.
    // Parameters:
    // caller - address that will perform the burn (must not be address(0))
    // amount - amount to burn (must be <= caller's balance in c)
    function run(address caller, uint256 amount) public {
        require(caller != address(0), "bad caller");
        // Precondition: ensure caller has enough balance to burn 'amount'.
        // If caller is not owner, we need owner to mint them tokens first so non-owner can attempt burn.

        address ownerAddr = c.owner();

        // If caller has insufficient balance, mint from owner to caller.
        uint256 bal = c.balanceOf(caller);
        if (bal < amount) {
            // must be called by owner, so use the known owner: we emulate owner calling mintToken
            // but we can only call through this contract; current msg.sender is this contract.
            // The original C's onlyOwner uses msg.sender == owner; so to have owner call, the provided C
            // instance must already have owner == address(this). If not, we cannot mint on behalf of owner.
            // To make the test general, require owner equals this contract OR caller already had balance.
            require(ownerAddr == address(this), "unable to mint: test contract not owner and caller lacks balance");
            c.mintToken(caller, amount - bal);
        }

        // Record totalSupply before burn
        uint256 before = c.totalSupply();

        // Execute burn from caller by using a low-level call to forward msg.sender as caller.
        // We cannot change msg.sender, so we require the provided caller to be address(this) when owner behavior is needed;
        // To perform the burn as 'caller', the only practical option in this test is to require caller == address(this)
        // or that caller already had balance and owner==caller so they can call directly. Enforce that.
        require(caller == address(this) || caller == ownerAddr, "caller must be test contract or owner");

        // If caller is this contract, perform burn here (this contract is msg.sender)
        if (caller == address(this)) {
            // this contract must have sufficient balance (ensured above)
            c.burn(amount);
        } else {
            // caller == ownerAddr: owner is externally owned; we cannot make an EOA call here as that would change msg.sender.
            // However, if owner == address(this) then previous branch handled it. So this branch is unreachable under constraints.
            // Keep for clarity but do nothing.
        }

        uint256 after = c.totalSupply();

        // General rule: only owner can decrease totalSupply via burn. So if msg.sender is not owner, totalSupply must not decrease.
        // Here the effective caller is address(this) when we executed burn above.
        bool iamOwner = (address(this) == ownerAddr);
        if (!iamOwner) {
            // If this contract is not owner, burn should not have reduced totalSupply.
            assert(after == before);
        } else {
            // If this contract is owner, burn should reduce totalSupply by amount.
            assert(after + amount == before);
        }
    }

    // allow receiving ether if needed by environment
    receive() external payable {}
}

