contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address burner, uint256 value) public payable {
        // precondition: ensure burner has enough balance to call burn
        require(burner != address(0));
        // record totalSupply before the call
        uint256 supplyBefore = c.totalSupply();
        // call burn from the burner address
        // we must call via address(this) performing a call on behalf of burner using low-level call
        // so we use a contract call: create calldata for burn(uint256)
        (bool success, ) = address(c).call(abi.encodeWithSignature("burn(uint256)", value));
        // Note: The above call originates from this contract, not `burner`. To simulate a call from `burner`,
        // we require that burner == address(this) for the test to be meaningful; otherwise the observed behavior
        // under P (onlyOwner) vs M (anyone) differs only when the caller is not owner. Therefore enforce burner == address(this) or that address(this) is owner.
        // Enforce that the externally-specified burner equals this contract to ensure the call's sender is controlled here.
        require(burner == address(this));
        // After the burn attempt, read totalSupply
        uint256 supplyAfter = c.totalSupply();
        // General rule: if the caller is not the owner, totalSupply must not decrease
        address owner = c.owner();
        if (address(this) != owner) {
            assert(supplyAfter >= supplyBefore);
        } else {
            // If this contract is the owner, totalSupply should decrease by at most `value` and not increase
            assert(supplyAfter <= supplyBefore);
        }
    }
    receive() external payable { }
}

contract InvMutTest {
