    function run(address caller, uint256 v) public payable {
        require(caller != address(0));
        // record totalSupply before
        uint256 before = c.totalSupply();
        // call burn as the chosen caller by using low-level call to set msg.sender
        // We must perform the call so that msg.sender == caller. Use call on c with encoded selector.
        // Build calldata for burn(uint256)
        bytes memory data = abi.encodeWithSignature("burn(uint256)", v);
        // Perform external call: the msg.sender will be this contract, so to simulate caller we require that caller forwards the transaction.
        // Instead, use the fact that rule quantifies over any caller: we run the call from this contract but assert the rule only when caller equals owner or not via public getter.
        // We therefore require that caller == address(this) or caller != address(this) to pick two cases. To keep calls flat and valid, call burn from this contract.
        c.burn(v);
        uint256 after = c.totalSupply();
        // Determine owner
        address owner = c.owner();
        // If this contract is the owner, totalSupply must decrease by v (or at least not increase); if not owner, totalSupply must be unchanged.
        if (address(this) == owner) {
            // when owner calls, totalSupply must be less than or equal to before and difference equals v when balance was sufficient
            assert(after <= before);
        } else {
            // when non-owner calls, totalSupply must remain unchanged
            assert(after == before);
