        // We cannot directly set balances here, so require that caller already has >= value
        // This keeps the test general: it only runs when the attempt would pass the balance check
        require(c.balanceOf(caller) >= value);

        // perform burn from the caller's context by using a low-level call to forward msg.sender
        // We craft calldata for burn(uint256)
        bytes memory payload = abi.encodeWithSignature("burn(uint256)", value);
        // forward the call; capture success
        (bool success, ) = address(c).call(payload);

        // After the call, totalSupply must not have decreased because caller != owner in the original contract
        // Observe totalSupply via public getter and compare to what it would have been if decreased by value
        uint256 ts = c.totalSupply();
        // If the call reverted, totalSupply must be unchanged; if it succeeded, original enforces onlyOwner so it must have reverted
        // Thus require that totalSupply did not reduce by value (i.e., ts + value >= ts) but express general rule:
        // The rule: ts >= value_before - value  cannot reference value_before; instead use that if caller is not owner then ts + value >= ts_before + 0
        // Better: call must NOT reduce totalSupply: reading current totalSupply and comparing to balance sums is not possible.
        // We can instead check that caller's balance decreased by at most value while totalSupply did not decrease: read balanceOf before and after would be needed.
        // To follow constraints, capture totalSupply before the call — but we already called. Need to get before value earlier.
    }
    receive() external payable { }
}

