import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, 0, 0); }

    // Fuzzed params: actor (address) who will attempt burn and amount to burn.
    function testFuzz_property(address actor, uint256 amt) public {
        // Keep wide domain but avoid zero-address for meaningful actor
        vm.assume(actor != address(0));
        // Give actor some ETH so he can be a pranked sender (not necessary but harmless)
        vm.deal(actor, 1 ether);

        // The reference contract sets owner = deployer (this contract), and initially totalSupply = 0
        // To make burn observable, mint some tokens to the actor from the owner first.
        // Bound minted amount to reasonable size to avoid overflow edgecases in test harness
        uint256 mintAmount = bound(amt, 0, type(uint256).max / 2);

        // Owner (this test contract) mints tokens to actor
        c.mintToken(actor, mintAmount);

        // Record totalSupply after mint (should equal mintAmount)
        uint256 beforeTotal = c.totalSupply();

        // Ensure actor has at least some balance to attempt burn; if mintAmount==0 then burning 0 is allowed but no change occurs
        vm.prank(actor);
        bool ok;
        try c.burn(mintAmount) {
            ok = true;
        } catch {
            ok = false;
        }

        uint256 afterTotal = c.totalSupply();

        // General property to assert: In the correct contract, only owner can burn, so any non-owner actor's attempt
        // to burn the actor's own balance must NOT decrease totalSupply. Thus, for any actor != owner, afterTotal == beforeTotal.
        // This single assert reads c via its public getter totalSupply().
        if (actor != address(this)) {
            assertTrue(afterTotal == beforeTotal);
        } else {
            // If actor == owner (this contract), owner burning is allowed, so totalSupply may decrease; we do not assert in that case.
            assertTrue(true);
        }
    }
}

