    // General rule: in the reference contract only the owner can successfully call burn to reduce totalSupply;
    // therefore for every non-owner caller and any amount, either burn reverts or totalSupply stays the same when observed via the public getter.
    // The mutant removes onlyOwner, so there exist non-owner callers and amounts where burn succeeds and reduces totalSupply.
    function testFuzz_property(address caller, uint256 amount) public {
        // Keep caller non-zero to be an admissible EOA
        vm.assume(caller != address(0));

        uint256 before = c.totalSupply();

        // Ensure caller has sufficient balance to attempt burn by giving them tokens via owner (setUp deployer is owner)
        // The deployer (address(this)) is owner; mint some tokens to the fuzzed caller to allow burn to potentially succeed.
        uint256 mintAmount = amount;
        // Bound mintAmount to avoid overflow in tests; still wide.
        if (mintAmount > type(uint256).max / 2) mintAmount = type(uint256).max / 2;

        // mintToken is onlyOwner, so call as owner (this contract) to provision caller with balance
        c.mintToken(caller, mintAmount);

        // Now simulate caller calling burn(amount)
        bool ok;
        // Prank as the caller
        vm.prank(caller);
        try c.burn(amount) returns (bool ret) {
            ok = ret;
        } catch {
            ok = false;
        }

        uint256 after = c.totalSupply();

        // Single assertion: In the reference, only the owner can reduce totalSupply; therefore if the caller is not the owner
        // then after should equal before (i.e., non-owner cannot decrease totalSupply). The mutant that removed onlyOwner
        // will allow some non-owner calls to succeed and thereby make after < before for some inputs.
        // We express the general rule as: if caller != owner then totalSupply must remain unchanged after their burn attempt.
        // Read owner via public getter: owner()
        address owner = c.owner();
        if (caller != owner) {
            assertTrue(after == before);
        } else {
            // If caller is owner, burn may succeed (or not depending on amount); still must be a valid observation through public API.
            // We simply assert that the contract behaved consistently: if burn returned true then totalSupply decreased by at most amount,
            // but to keep a single simple invariant that passes on reference for all inputs we accept any result for owner.
            assertTrue(true);
        }
    }
}

