pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    address owner;

    function setUp() public { c = new C(0, 0, 0); owner = address(this); }

    // Fuzz parameters: an arbitrary caller and an arbitrary burn amount
    function testFuzz_property(address caller, uint256 amount) public {
        // Keep domain wide but make caller non-zero
        vm.assume(caller != address(0));

        // Ensure caller has funds to attempt burn when not owner.
        // For the reference contract, only the owner (this) initially has the totalSupply.
        // We transfer some tokens to the fuzzed caller so they might be able to call burn in the mutant.
        uint256 seedAmount = bound(amount, 0, type(uint128).max);

        // Transfer from owner (this) to caller so caller may hold balance.
        // c.transfer is called from owner by default (this contract), so it will succeed.
        // Bound transfer amount to available supply to avoid underflow in _transfer.
        uint256 ownerBalance = c.balanceOf(address(this));
        uint256 transferAmt = seedAmount;
        if (transferAmt > ownerBalance) transferAmt = ownerBalance;
        if (transferAmt > 0) {
            bool ok = c.transfer(caller, transferAmt);
            // transfer should succeed; if not, keep going (no need to assume)
            (void)ok;
        }

        // Record totalSupply before burn attempt
        uint256 before = c.totalSupply();

        // Make the fuzzed caller call burn(amount)
        vm.prank(caller);
        bool ok;
        try c.burn(amount) {
            ok = true;
        } catch {
            ok = false;
        }

        // After call, totalSupply must not have decreased when caller is NOT the owner in the reference.
        // Because in the reference only the owner can burn, any non-owner call either reverts or leaves totalSupply unchanged.
        // We assert that if the caller is not the contract owner, then totalSupply >= before.
        // This reads the contract's public getter totalSupply and so is valid.
        if (caller != address(this)) {
            uint256 after = c.totalSupply();
            assertTrue(after >= before);
        } else {
            // If caller is owner, the owner is allowed to burn; the reference permits decreasing totalSupply.
            // For owner we cannot assert monotonicity, so simply assert true by checking the call's observed behavior
            // via its ok flag: owner burn either succeeds or reverts depending on funds; accept both.
            assertTrue(true);
        }
    }
}

