contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public function with all logic
    function run(address target, uint256 initialSupply, uint256 burnAmount) public {
        // preconditions: caller must be owner of c to call owner-only functions
        // require that this contract is the owner by checking balance can be minted to it and then used
        // We assume owner is msg.sender of C's constructor; ensure caller is that owner by requiring balance and ownership interactions.
        // Mint some tokens to this contract (must be owner). The test caller must be the owner of c.
        // Use require to ensure meaningful arithmetic and avoid underflow in the burn call.
        require(burnAmount > 0, "burnAmount>0");

