        require(c.balanceOf(address(this)) >= burnAmount, "insufficient balance to burn");

        // call burn as owner (this contract must be owner of C for this to succeed)
        c.burn(burnAmount);

        // observe totalSupply after burn
        uint256 supplyAfter = c.totalSupply();

        // General rule: supplyAfter == supplyBefore - burnAmount
        assert(supplyAfter == supplyBefore - burnAmount);
    }

    // allow contract to receive ether if needed by other tests (not used here)
    receive() external payable {}
}

