pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, 0, 0); }

    // General rule tested:
    // For any fuzzed address 'other' and fuzzed burn amount 'amt' such that the caller is owner
    // and the owner has at least amt funds, invoking burn(amt) decreases owner's balance by amt
    // and does NOT change 'other' account's balance. The mutant that emits Burn(owner, ..)
    // does not change balances differently in storage, but emitting owner instead of msg.sender
    // can be detected by observing that only the owner's balance changed while 'other' remains same.
    function testFuzz_property(address other, uint256 amt) public {
        // keep domain wide but sensible: other can be any address; amt must fit into owner's balance
        // owner is the test contract deployer (address(this) in setUp). c was created by this contract,
        // so the owner is address(this). The constructor gave totalSupply = 0 * 10**decimals = 0,
        // so mint some tokens to owner first via mintToken (onlyOwner) to enable burning.

        // Bound amt to a reasonable range so arithmetic doesn't underflow in the test harness
        uint256 maxMint = type(uint128).max; // wide
        uint256 mintAmt = bound(amt, 0, maxMint);

        // Mint tokens to owner (this test contract) so owner has balance to burn
        c.mintToken(address(this), mintAmt);

        // Record balances before burn
        uint256 ownerBefore = c.balanceOf(address(this));
        uint256 otherBefore = c.balanceOf(other);
        uint256 totalBefore = c.totalSupply();

        // Precondition: owner must have at least the amount to burn; if not, skip (admissible domain)
        vm.assume(ownerBefore >= mintAmt);

        // Owner calls burn(mintAmt)
        bool ok;
        try c.burn(mintAmt) {
            ok = true;
        } catch {
            ok = false;
        }

        // The reference always succeeds (owner is caller and has funds), so ok should be true
        // and balances should reflect owner's burn: owner's balance decreased by mintAmt,
        // totalSupply decreased by mintAmt, and other account's balance unchanged.
        // Single assertion observing contract public getters: combine checks into one boolean.
        uint256 ownerAfter = c.balanceOf(address(this));
        uint256 otherAfter = c.balanceOf(other);
        uint256 totalAfter = c.totalSupply();

        bool property = ok &&
                        ownerAfter + mintAmt == ownerBefore &&
                        totalAfter + mintAmt == totalBefore &&
                        otherAfter == otherBefore;

        assertTrue(property);
    }
}
